/**
 * Glyphs the desktop client draws with a stroke rather than a fill.
 *
 * The default icon pack ("mcode") is a fill set, so this list is deliberately
 * small: it holds only the glyphs whose upstream ref carries its own
 * `stroke`/`strokeWidth` plus the ones the desktop never ships a filled variant of
 * (the disclosure chevrons, the send arrow, the download arrow, the panel/terminal
 * outlines). Adding a name here turns its paths into stroked outlines, so it must
 * match the upstream ref rather than a visual guess.
 */
const STROKE_ICONS = new Set<IconName>([
  "download",
  "chevronRight",
  "arrowUp",
  "bell",
  "send",
  "reply",
  "chevronDown",
  "check",
  "sun",
  "mic",
  "share",
  "terminal",
  "workspace",
  "sidebar",
  "website",
]);

export function Icon({ name, size, className }: { name: IconName; size?: number; className?: string }) {
  const spec = ICONS[name];
  if (!spec) return null;
  const stroke = STROKE_ICONS.has(name);
  return (
    <svg
      width={size ?? spec.size}
      height={size ?? spec.size}
      viewBox={spec.viewBox}
      fill={stroke ? "none" : "currentColor"}
      stroke={stroke ? "currentColor" : "none"}
      strokeWidth={stroke ? 1.3 : undefined}
      strokeLinecap={stroke ? "round" : undefined}
      strokeLinejoin={stroke ? "round" : undefined}
      className={["flex-shrink-0", className].filter(Boolean).join(" ")}
      aria-hidden="true"
    >
      {spec.body}
    </svg>
  );
}